#!/usr/bin/env node

// Disclaimer: this slop was generated by AI and NOT checked because im lazy, and it works (sometimes)
// Very slightly modified
// Make sure you have both repositories in the same folder

import { readdirSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

const inputDir = __dirname + "/../arc-studio/packages/studio-server/src/engine/nodes";
const outputDir = __dirname + "/content/docs/nodes";
console.log(`INPUT DIR: ${inputDir}`);
console.log(`OUTPUT DIR: ${outputDir}`);
console.log("\nGenerating...\n");

function generateMdx(obj) {
  let mdx = `---\ntitle: "${obj.label}"\n---\n\n${obj.description}\n`;

  if (obj.inputs && obj.inputs.length > 0) {
    mdx += '\n## Inputs\n\n';
    mdx += '| Pin Name | Type | Default Value |\n';
    mdx += '| :-: | :-: | :-: |\n';
    obj.inputs.forEach(input => {
      console.log(input.defaultValue);
      mdx += `| ${input.label} | ${input.type} | ${input.defaultValue !== undefined ? input.defaultValue : ""} |\n`;
    });
  }

  if (obj.outputs && obj.outputs.length > 0) {
    mdx += '\n## Outputs\n\n';
    mdx += '| Pin Name | Type |\n';
    mdx += '| :-: | :-: |\n';
    obj.outputs.forEach(output => {
      mdx += `| ${output.label} | ${output.type} |\n`;
    });
  }

  return mdx.replaceAll("{", "\\{").replaceAll("}", "\\}");
}

async function processFiles() {
  if (!existsSync(inputDir)) {
    console.error(`❌ Input directory does not exist: ${inputDir}`);
    process.exit(1);
  }

  const files = readdirSync(inputDir, { recursive: true })
    .filter(file => {
      if (!file.endsWith('.js') && !file.endsWith('.jsx')) return false;
      if (file.startsWith('runtime/') || file.includes('/runtime/')) return false;
      return true;
    });

  let processed = 0;
  let skipped = 0;

  for (const file of files) {
    const fullPath = join(inputDir, file);

    try {
      const module = await import(fullPath);
      const obj = module.default;

      if (!obj || !obj.type) {
        console.log(`⏭️ | ${file} (no type/export)`);
        skipped++;
        continue;
      }

      const mdxContent = generateMdx(obj);

      // Calculate relative path from input directory
      const relativePath = relative(inputDir, dirname(fullPath));
      const outputSubdir = join(outputDir, relativePath);

      // Create output subdirectory if it doesn't exist
      mkdirSync(outputSubdir, { recursive: true });

      const outputFile = join(outputSubdir, `${obj.type}.mdx`);

      writeFileSync(outputFile, mdxContent, 'utf-8');
      console.log(`✅ | ${file}`);
      processed++;
    } catch (err) {
      console.error(`❌ | ${file}:`, err.message);
      skipped++;
    }
  }

  console.log(`\n🎉 Done! Generated ${processed} files. Skipped ${skipped}.`);
}

processFiles();
